REVOKE INSERT,UPDATE ON public.businesses FROM authenticated;
GRANT UPDATE(name,whatsapp,primary_color) ON public.businesses TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_catalog_values() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(new.name))<2 OR new.duration_minutes<5 OR new.duration_minutes>480 OR new.price_cents<0 THEN RAISE EXCEPTION 'invalid_service'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_catalog BEFORE INSERT OR UPDATE ON public.services FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_values();
CREATE OR REPLACE FUNCTION public.validate_tenant_hours() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.open_time IS NULL OR new.close_time IS NULL OR new.open_time::time>=new.close_time::time OR new.slot_interval_minutes<5 OR new.slot_interval_minutes>480 OR new.service_minutes<5 OR new.service_minutes>480 OR cardinality(new.open_weekdays)=0 OR NOT new.open_weekdays<@ARRAY[0,1,2,3,4,5,6] OR (new.lunch_start IS NULL)<>(new.lunch_end IS NULL) THEN RAISE EXCEPTION 'invalid_hours'; END IF; IF new.lunch_start IS NOT NULL AND new.lunch_start::time>=new.lunch_end::time THEN RAISE EXCEPTION 'invalid_lunch'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_tenant_hours BEFORE INSERT OR UPDATE ON public.tenant_settings FOR EACH ROW EXECUTE FUNCTION public.validate_tenant_hours();